import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth'; // Adjust path if needed

const RestaurantAdminDashboardPage = () => {
  const { user } = useAuth();

  return (
    <div>
      <h2>Restaurant Admin Dashboard</h2>
      {user && <p>Welcome, {user.username}!</p>}
      <p>Manage your restaurant here:</p>
      <ul>
        <li><Link to="/restaurant/manage">Manage Restaurant Details</Link></li>
        <li><Link to="/restaurant/menu/add">Add New Menu Item</Link></li>
        <li><Link to="/restaurant/menu/edit">Edit Existing Menu Items</Link></li>
        {/* Add links to other restaurant admin functionalities */}
      </ul>
    </div>
  );
};

export default RestaurantAdminDashboardPage;
